node -e "
const Database = require('better-sqlite3');
const db = new Database('/workspace/world.db');

// Check orders table structure
const info = db.prepare('PRAGMA table_info(orders)').all();
console.log('COLUMNS:', JSON.stringify(info.map(c => c.name)));

// Search for the order
const orders = db.prepare(\"SELECT * FROM orders WHERE order_id LIKE '%D7E869%' OR order_id LIKE '%d7e869%'\").all();
console.log('MATCHED ORDERS:', JSON.stringify(orders, null, 2));

// Also check all orders for this user
const userOrders = db.prepare(\"SELECT * FROM orders WHERE user_id = 'user_d3d5d0c8'\").all();
console.log('USER ORDERS:', JSON.stringify(userOrders, null, 2));
"

